// Написан autotest-writer вручную (2 роли — генератор не умеет). spec: .qa/e2e/specs/gifts.md 2.1; кейсы .qa/tests/gifts/GIFT-01…03, GIFT-04 («חדשה»).
// ПОДГОТОВКА: грант «הענקת מתנה» для new02 («QA П2 0011») в админке перед каждым прогоном — без него тест падает с подсказкой (ОКРУЖЕНИЕ).
// УБОРКА: подарок и сообщения удалить нельзя — остаются в чате new02↔new10 (77cad0cb), пометка cleanup. Ответ new10 снимает запрет «до ответа».
// Не проверен на живой странице (кнопка 🎁 в чате, поле сообщения, «חדשה») — проверить при первом /qa-regress.
import { test, expect } from '../../fixtures';
import { saveSession } from '../_shared/session';
import { N2, N10, phone, openChat, openReceivedGifts, receivedRows, openGiftSheet, giftMessageField, freeSendButton, awaitingReplyHint, closeGiftSheet } from './gifts-helpers';

test.describe('Подарки: отправка new02 → new10', () => {
  test.describe.configure({ mode: 'serial', timeout: 240_000 });

  test('Бесплатный подарок: «המתנה נשלחה», карточки у обоих, превью и «חדשה» у получательницы; повтор до ответа запрещён (UI + 400 awaiting_reply), после ответа — можно @iphone @data (#75332d #ecc349 #9a50b0 #9d9088)', async ({ asUser }) => {
    const s = await asUser('new02');
    const r = await asUser('new10');
    const msg = `QA-AUTO gifts ${Date.now()}`;
    let sent = false;
    let replied = false;
    try {
      await phone(s);
      await phone(r);

      // 1–2. new02: чат → 🎁 → сообщение → «שליחת מתנה • חינם».
      await openChat(s, N10);
      await openGiftSheet(s);
      await expect(awaitingReplyHint(s, N10), 'предыдущий подарок уже с ответом (иначе ответь вручную new10 → чат «QA П2 0011»)').toHaveCount(0);
      const btn = freeSendButton(s);
      await expect(btn, 'нет бесплатного подарка: выдай грант «הענקת מתנה» new02 в админке (magnet-admin → משתמשים → QA П2 0011)').toBeEnabled({ timeout: 15_000 });
      await expect(s.getByText(new RegExp(`כך ${N10} (יראה|תראה) את זה`))).toBeVisible();
      await giftMessageField(s).fill(msg);
      await expect(s.getByText(`${msg.length}/140`)).toBeVisible();
      const wait = s.waitForResponse((x) => x.url().includes('/rpc/send_gift') && x.request().method() === 'POST');
      await btn.click();
      const res = await wait;
      expect(res.ok(), `send_gift: ${res.status()} ${await res.text()}`).toBeTruthy();
      sent = true;
      const req = res.request();
      const reqHeaders = await req.allHeaders();
      const reqBody = req.postDataJSON();
      await expect(s.getByRole('button', { name: 'המתנה נשלחה' }).or(s.getByText('המתנה נשלחה')).first()).toBeVisible();

      // Карточка у отправителя: «שלחת מתנה», «ורד זהב», сообщение (#ecc349 AC 4).
      await openChat(s, N10);
      await expect(s.getByText(msg).last()).toBeVisible({ timeout: 30_000 });
      await expect(s.getByText(/שלחת מתנה/).last()).toBeVisible();

      // 3. new10 до открытия чата: превью в /matches и «חדשה» в «המתנות שקיבלתי».
      await expect(async () => {
        await r.goto('/matches');
        const row = r.getByRole('button', { name: new RegExp(`^${N2}`) }).first();
        await expect(row).toContainText(/לך מתנה/, { timeout: 10_000 });
      }, 'превью «… לך מתנה» у получательницы (#ecc349 AC 5–6)').toPass({ timeout: 60_000 });
      await openReceivedGifts(r);
      const top = receivedRows(r, N2).first();
      await expect(top).toContainText(msg);
      await expect(top).toContainText('חדשה');

      // 4. new10 открывает чат: входящая карточка (#75332d AC 5, 7; #ecc349 AC 1–3).
      await openChat(r, N2);
      await expect(r.getByText(msg).last()).toBeVisible({ timeout: 30_000 });
      await expect(r.getByText(new RegExp(`${N2} שלח(ה)? לך מתנה`)).last()).toBeVisible();
      await expect(r.getByText('ורד זהב').last()).toBeVisible();

      // 5. Повтор до ответа: подсказка в UI и отказ сервера.
      await openGiftSheet(s);
      await expect(awaitingReplyHint(s, N10)).toBeVisible();
      const again = await s.request.post(req.url(), {
        headers: { apikey: reqHeaders['apikey'], authorization: reqHeaders['authorization'], 'content-type': 'application/json' },
        data: reqBody,
        failOnStatusCode: false,
      });
      const againText = await again.text();
      expect(again.status(), `повторный send_gift до ответа: ${againText}`).toBe(400);
      expect(againText).toContain('awaiting_reply');
      await closeGiftSheet(s);

      // 6. Ответ new10 снимает запрет.
      const reply = `${msg} reply`;
      await r.getByRole('textbox', { name: 'כתוב הודעה' }).fill(reply);
      const w2 = r.waitForResponse((x) => x.url().includes('/rest/v1/messages') && x.request().method() === 'POST');
      await r.getByRole('button', { name: 'שליחה' }).click();
      expect((await w2).ok(), 'ответ new10 отправлен').toBeTruthy();
      replied = true;
      await expect(s.getByText(reply).last()).toBeVisible({ timeout: 30_000 });

      // 7. new02: подсказки «до ответа» больше нет.
      await expect(async () => {
        await openChat(s, N10);
        await openGiftSheet(s);
        await expect(awaitingReplyHint(s, N10)).toHaveCount(0, { timeout: 5_000 });
      }).toPass({ timeout: 60_000 });
    } finally {
      if (sent) test.info().annotations.push({ type: 'cleanup', description: `подарок «ורד זהב» new02→new10 «${msg}»${replied ? ' + ответ new10' : ''} — в чате 77cad0cb, удалить нельзя (в список чистки); грант new02 потрачен` });
      if (sent && !replied) test.info().annotations.push({ type: 'cleanup', description: 'new10 НЕ ответила — ответь вручную (new10 → чат «QA П2 0011»), иначе следующий прогон упрётся в awaiting_reply' });
      await saveSession(s, 'new02');
      await saveSession(r, 'new10');
    }
  });
});
